import sqlite3
import hashlib
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email) VALUES ('admin', ?, 'admin', 'admin@internal.corp')", (admin_hash,))
    db.commit()
    db.close()

@app.route('/api/user/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Restrict searchable fields to prevent information disclosure
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Build query with field validation above
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'users': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/user/profile', methods=['GET'])
def get_profile():
    """Get user profile by API key authentication."""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    user = db.execute(
        "SELECT username, email, role FROM users WHERE api_key = ?",
        (api_key,)
    ).fetchone()

    if not user:
        return jsonify({'error': 'Invalid API key'}), 401
    return jsonify(dict(user))

@app.route('/api/user/reset', methods=['POST'])
def reset_password():
    """Password reset - requires username and email verification."""
    data = request.get_json()
    username = data.get('username', '')
    email = data.get('email', '')
    new_password = data.get('new_password', '')

    if not all([username, email, new_password]):
        return jsonify({'error': 'Missing fields'}), 400

    db = get_db()
    user = db.execute(
        "SELECT id FROM users WHERE username = ? AND email = ?",
        (username, email)
    ).fetchone()

    if not user:
        return jsonify({'error': 'User not found'}), 404

    new_hash = hashlib.sha256(new_password.encode()).hexdigest()
    db.execute("UPDATE users SET password_hash = ? WHERE id = ?", (new_hash, user['id']))
    db.execute("INSERT INTO audit_log (action, username) VALUES ('password_reset', ?)", (username,))
    db.commit()
    return jsonify({'status': 'password updated'})

@app.route('/api/admin/export', methods=['GET'])
def export_users():
    """Admin endpoint - exports user list for compliance."""
    auth = request.headers.get('Authorization')
    if auth != f"Bearer {os.environ.get('ADMIN_TOKEN', '')}":
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    users = db.execute("SELECT username, email, role FROM users").fetchall()
    return jsonify({'users': [dict(u) for u in users]})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
